<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api} from '../api'
import {ElMessage} from 'element-plus'
const props=defineProps<{modelValue:boolean;role:any;editable:boolean}>(),emit=defineEmits(['update:modelValue'])
const table=ref()
const authorized=ref('1'),name=ref(''),dept=ref<number>(),departments=ref<any[]>([]),rows=ref<any[]>([]),selected=ref<any[]>([]),page=ref(1),limit=ref(20),total=ref(0)
async function load(){const result=await api(`/api/system/role/${props.role.id}/users/`,{params:{authorized:authorized.value,name:name.value,dept:dept.value,page:page.value,limit:limit.value}});rows.value=result.data;total.value=result.total}
function search(){table.value.clearSelection();selected.value=[];page.value=1;load()}
async function change(){await api(`/api/system/role/${props.role.id}/users/`,{method:'PUT',data:{operation:authorized.value==='1'?'remove':'add',ids:selected.value.map(x=>x.id)}});ElMessage.success('用户授权已更新');table.value.clearSelection();selected.value=[];await load()}
onMounted(async()=>{departments.value=(await api('/api/system/dept/options/')).data;await load()})
</script>
<template><el-drawer :model-value="modelValue" :title="role.name+' · 授权用户'" size="min(850px, 100vw)" @update:model-value="(value:boolean)=>emit('update:modelValue',value)"><el-radio-group v-model="authorized" @change="search"><el-radio-button value="1">已授权</el-radio-button><el-radio-button value="0">未授权</el-radio-button></el-radio-group><div class="user-filters"><el-input v-model="name" placeholder="姓名 / 登录账号" clearable @keyup.enter="search"/><el-select v-model="dept" clearable filterable placeholder="部门"><el-option v-for="item in departments" :key="item.id" :value="item.id" :label="item.name"/></el-select><el-button @click="search">查询</el-button></div><el-popover trigger="click" width="min(450px, calc(100vw - 24px))"><template #reference><el-button>已选 {{selected.length}} 人</el-button></template><el-tag v-for="user in selected" :key="user.id" closable @close="table.toggleRowSelection(user,false)">{{user.name||user.username}}</el-tag><el-button text @click="table.clearSelection()">清空选择</el-button></el-popover><el-table ref="table" row-key="id" :data="rows" @selection-change="(values:any[])=>selected=values"><el-table-column v-if="editable" type="selection" :reserve-selection="true" width="48"/><el-table-column prop="username" label="登录账号" min-width="140"/><el-table-column prop="name" label="姓名" min-width="140"/><el-table-column prop="dept_path" label="部门" min-width="180"/></el-table><el-pagination v-model:current-page="page" v-model:page-size="limit" :total="total" layout="prev,pager,next,total" @change="load"/><template #footer><el-button @click="emit('update:modelValue',false)">关闭</el-button><el-button v-if="editable" type="primary" :disabled="!selected.length" @click="change">{{authorized==='1'?'取消选中授权':'添加选中用户'}}</el-button></template></el-drawer></template>
<style scoped>.user-filters{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.user-filters>.el-input,.user-filters>.el-select{flex:1;min-width:160px}.el-pagination{margin-top:16px;flex-wrap:wrap}</style>
